SELECT id, device, browser, started_at, country, ROW_NUMBER() OVER (PARTITION BY browser, customer_id ORDER BY started_at DESC, id) AS row_seq, ROW_NUMBER() OVER w_ordered AS row_seq_2, LAST_VALUE(country, TRUE) OVER (PARTITION BY device, customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, FIRST_VALUE(browser, TRUE) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser FROM sessions WINDOW w_ordered AS (PARTITION BY country, device ORDER BY started_at, id);
